# Review package: 2ef711d2..HEAD

## Commits
9cf3370d test(runtime-tokio): SMA-869 pin a cancelled resume through a handoff

## Files changed
 .../tests/deferred.rs                              | 39 ++++++++++++++++++++++
 1 file changed, 39 insertions(+)

## Diff
diff --git a/crates/paigasus-helikon-runtime-tokio/tests/deferred.rs b/crates/paigasus-helikon-runtime-tokio/tests/deferred.rs
index 3707ef08..27376f42 100644
--- a/crates/paigasus-helikon-runtime-tokio/tests/deferred.rs
+++ b/crates/paigasus-helikon-runtime-tokio/tests/deferred.rs
@@ -1339,20 +1339,59 @@ async fn deferral_with_the_call_id_of_a_transfer_call_defers() {
     assert_eq!(result.final_output, "done");
     assert_eq!(resume_pay.calls().len(), 1, "pay runs once on resume");
     assert!(open_ids(&session).await.is_empty());
     let requests = resume_model.requests();
     assert_eq!(requests.len(), 1);
     for r in &requests {
         assert_tool_calls_paired(&r.messages);
     }
 }

+#[tokio::test]
+async fn prefired_cancel_on_handoff_resume_runs_no_approved_call() {
+    let session = handoff_session().await;
+    let pay = PayTool::new();
+    let budgeting = pay_agent(
+        "budgeting",
+        RequestLog::with_scripts(vec![text_turn("never")]),
+        &pay,
+    );
+    let triage = LlmAgent::builder::<()>()
+        .name("triage")
+        .shared_model(RequestLog::with_scripts(vec![]))
+        .handoff(budgeting)
+        .build();
+    let input = resolve_all(&session, ToolResolution::Approved).await;
+    let cancel = CancellationToken::new();
+    cancel.cancel();
+    let ctx = ctx(session.clone(), true).with_cancel(cancel);
+
+    let mut stream = TokioRunner
+        .run_streamed(&triage, ctx, input, RunConfig::default())
+        .await
+        .expect("stream starts")
+        .events;
+    let mut events = Vec::new();
+    while let Some(ev) = stream.next().await {
+        events.push(ev);
+    }
+
+    assert!(
+        !events
+            .iter()
+            .any(|e| matches!(e, AgentEvent::AgentUpdated { .. })),
+        "the parent hands off no run after a cancel: {events:?}"
+    );
+    assert_eq!(pay.calls().len(), 0);
+    assert!(open_ids(&session).await.is_empty());
+}
+
 #[tokio::test]
 async fn deferral_with_a_unique_call_id_after_a_handoff_still_defers() {
     let (result, session, pay, child_model) = handoff_run_with_ids("t1", "fc_0").await;

     assert!(
         matches!(&result.stop_reason, StopReason::Deferred { calls } if calls.len() == 1),
         "{:?}",
         result.stop_reason
     );
     assert!(pay.calls().is_empty());

